def val(town, svc, row, field):
    """1つの値を取り出す。"""
    return TOKEI[town][svc][ROWS.index(row)][FIELDS.index(field)]


def koiki(svc, row, field):
    """3町を合計して広域連合単位の値とする。"""
    return sum(val(t, svc, row, field) for t in TOWNS)


SERVICES = list(TOKEI['東川町'].keys())

# 審査月8月分の主な合計（38介護給付費計の「計」の行）
GOKEI = {f: {t: val(t, '38介護給付費計', '計', f) for t in TOWNS}
         for f in ['利用実人員', '単位数', '費用総額', '介護給付費', '特定入所費', '社福軽減額']}

