# 明細の実人数（被保険者番号の異なり数。要介護度別の和ではなくファイル単位で数えたもの）
MEISAI_JINZU = {'訪問介護': 278, '訪問入浴介護': 12, '訪問看護': 136,
                '訪問リハビリテーション': 51, '介護予防訪問看護': 22,
                '介護予防訪問入浴介護': 0}


def meisai_kei(svc):
    """明細の集計（明細行数・実人数・単位数・日数／回数）。実人数は MEISAI_JINZU による。"""
    d = MEISAI[svc]
    return (sum(v[0] for v in d.values()), MEISAI_JINZU[svc],
            sum(v[2] for v in d.values()), sum(v[3] for v in d.values()))
